(function(define) {
_define = define;

var lib = {};

lib.module = function(name, fn) {
    var mod = {};
    _define(mod, name);
    fn(mod);
    return mod;
};

lib.dependency = function(fn) {
    var deps = [];
    for(var arg in arguments) {
        if(arguments.hasOwnProperty(arg)) {
            deps.push(arguments[arg]);
        }
    }

    var ret;

    // wait til dependencies have loaded
    _define(function(self) {
        self.loaded = false;
        function load() {
            var error, i, len;
            for(i = 0, len = deps.length; i < len; ++i) {
                if(!deps[i].loaded) {
                    error = deps[i].load();
                    break;
                }
            }

            if(error) {
                self.loaded = false;
                throw error;
            } else {
                self.loaded = true;

                // call fn passing in dependencies
                ret = fn.apply(self, deps);
            }
        }
        load();
    });

    return {
        loaded: function() {return ret !== undefined;}
    };
};

lib.load = function(name) {
    var mod = _define[name];
    if(!mod.loaded()) {
        throw new Error("Module '" + name + "' not yet loaded");
    }
    return mod;
};

// expose module to global scope
window.module = lib;

})(function(fn, name) {
    fn(_define, name);
});
